"""Save source-reviewed local roles and current launch instructions."""
import hashlib,json,shutil
from pathlib import Path
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[1]
save=lambda p,v:p.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n')

def main():
    review=json.loads((ROOT/'verification/firmware-post-GPU-review.json').read_text());out=Path(review['directory'])
    local=Path(json.loads((ROOT/'verification/easy-firmware-post-GPU-scope-pointer.json').read_text())['directory']);run=json.loads((local/'protocol.json').read_text());item=run['results'][0]
    assert run['status']=='completed_pending_coordinator_review' and item['words']==87 and not item['quality_flags']
    assert all(x in item['answer']for x in ['15 CPU instructions','433 steps/20 checkpoints','six explicit video events','original CPU','no disc-header loading verified','cannot boot yet'])
    result=dict(status='local_post_GPU_CPU_and_attached_disc_scope_source_review_accepted',directory=str(local),words=item['words'],seconds=item['seconds'],interface='LM Studio SDK; no new native Chat test',evidence_tool_calls=1,roles_in_one_answer=['Analyst','Restorer','Reviewer'],same_model_weights=True,independent_model_verification=False,new_weight_training=False,coordinator_review='Checked against 15-instruction/433-step/20-checkpoint proof and attached-CDI source trace. C copy/wait, original follow-up CPU/video events, BIOS reentry/DSP wait, no injected stub, no verified disc header/loading and incomplete full boot are correctly stated. Separate connected game chain refers to the older game-component chain, not a verified connection from this firmware boot.',unproven='One diagnostic question does not establish general reliability, independent multi-model verification, completed decompilation or future hardware performance.')
    save(local/'coordinator-review.json',result);save(out/'local-review.json',result)
    with (out/'who-prompts-and-responses.txt').open('a')as f:f.write('\nLOCAL INFERENCE — EXACT MESSAGES\n'+(local/'prompts-and-responses.txt').read_text()+'\nCOORDINATOR REVIEW\n'+json.dumps(result,indent=2)+'\n')
    for name in ['START HERE.txt','CURRENT DECOMPILATION.txt','CURRENT LOCAL INFERENCE.txt']:shutil.copy2(ROOT/name,out/('prior-'+name))
    files=[ROOT/'scripts/test_firmware_post_GPU_chat_scope.py',ROOT/'scripts/record_firmware_post_GPU_local_review.py',local/'protocol.json',local/'prompts-and-responses.txt',local/'coordinator-review.json']
    for i,p in enumerate(files):
        target=out/f'local-{i:02d}-{p.name}';shutil.copy2(p,target);review['manifest'].append(dict(source=str(p),snapshot=str(target),sha256=hashlib.sha256(target.read_bytes()).hexdigest()))
    review['local_review']=result;save(out/'review.json',review);save(ROOT/'verification/firmware-post-GPU-review.json',review)
    now=datetime.now(timezone.utc).isoformat();summary=review['evidence']['plain_language_summary']
    native=ROOT/'verification/firmware-relocation-review/20261015T011820.772829Z/native-chat-export.md'
    (ROOT/'START HERE.txt').write_text(f'''LOCAL AI LAB — START HERE\nUpdated {now}\n\nEASY LOCAL CHAT\nDouble-click Game Model.command or Advertising Model.command in this folder. Both load the everyday advertising-scholar model and open LM Studio. In Chat, select the Game Assistant or Advertising Assistant preset and enable local-ai-lab. The everyday model remains 27B/6bit, 32,768 context, one worker.\nAsk: What CPU code is now reconstructed after GPU shutdown, and can the full rebuilt game boot yet?\nFor the sequential research/restoration workflows, use Game Team.command or Advertising Team.command. Their role outputs and exact prompts are saved in the run folders.\n\nGAME PROGRESS\n{summary}\n\nLOCAL OUTPUT TEST\nOne evidence lookup produced an accurate 87-word Analyst/Restorer/Reviewer answer in {item['seconds']:.2f} seconds through LM Studio SDK. All three labels are roles in one answer from the same weights. No new native Chat test or weight training this turn.\n{out/'who-prompts-and-responses.txt'}\n\nVERIFICATION SCOPE CORRECTION\nBlitter MMIO registers are included in TOM snapshots. The pinned core does not export private Blitter state; earlier descriptions of a separate private-state comparison were too broad. Global timing/prefetch bus cycles remain unverified.\n\nNATIVE CHAT\nEarlier visible Chat tool call and responses:\n{native}\n\nADVERTISING\nAdvertising Analysis Pilot v2 is trained, exported and loadable but experimental after semantic/rubric/tool-format failures. Everyday base stays the default.\n{ROOT/'verification/advertising-analysis-v2-review.json'}\n\nCURRENT AUDIT\n{out/'review.json'}\n''')
    current=ROOT/'CURRENT DECOMPILATION.txt';previous=current.read_text();current.write_text(f'POST-GPU CPU COPY/WAIT C VERIFIED; ATTACHED DISC BOOT LOOP DISCOVERED\n{now}\n\n{summary}\n\nPROOF\n15/15 reached source instructions, 433 executed steps, 20 first-use/periodic checkpoints. Full logical CPU/registers/flags/both stack banks, private2MB RAM, available peripheral snapshots, source PC traces/counts match. Guard rejects modified first instruction with status7, CPU/RAM unchanged and no fallback. Live CPU export uses computed registers/PC without a pulse reset or captured CPU boundary. Source RAM copy creates the1000 program; no host program copy.\n\nFOLLOW-UP DISCOVERY\nSix explicit video events use original CPU handlers/follow-ups. The fifth installs source vector1026; the sixth restores194C90, clears the counter and reaches source jump back into802000, then DSP wait5021C. Same loop occurs with internal CDI attached. Disc header/loading/game dispatch and physical timing are not verified. MAME documents a processor-specific ROM-read reset workaround; retained only as a diagnostic lead, not adopted as hardware truth or C equivalence.\n\nSCOPE CORRECTION\n{review["source_scope_correction"]}\n\nLOCAL TEST\n87 words/{item["seconds"]:.2f} seconds, one evidence tool call, normal EOS; source scope accepted. Same model plays all roles; no new training or native Chat UI test.\n\nAUDIT\n{out}\n\nNEXT\n{review["evidence"]["next_GPU_CPU_dependency"]["next_action"]}\n\nEARLIER CHECKPOINTS (historical scopes; the Blitter correction above supersedes broader claims)\n'+previous)
    (ROOT/'CURRENT LOCAL INFERENCE.txt').write_text(f'''CURRENT LOCAL INFERENCE\nUpdated {now}\n\nEveryday advertising-scholar:27B/6bit,32,768context,one worker; daily weights/presets unchanged. Use Game Model.command or Advertising Model.command, then Game Assistant or Advertising Assistant in LM Studio Chat with local-ai-lab enabled. Sequential teams remain available through Game Team.command and Advertising Team.command.\n\nNEW SDK OUTPUT TEST\nOne natural source question, one project_evidence lookup, 87-word Analyst/Restorer/Reviewer answer in {item['seconds']:.2f} seconds. Normal EOS; coordinator accepted scope after comparison with source evidence. These are three labels in one model answer, not independent agents or model verification.\n{out/'who-prompts-and-responses.txt'}\n{out/'local-review.json'}\n\nSOURCE PROGRESS\n{summary}\n{out/'review.json'}\n\nNATIVE CHAT\nEarlier visible tool call and role answers remain in “BIWN — Local Roles and Firmware Checkpoint.” No new native Chat test or MCP process refresh verified this turn. Background SDK work follows the request to proceed when locked. No Chat history injection.\n{native}\n\nADVERTISING\nAnalysis Pilot v2 is trained, exported and loadable, but semantic/grammar/rubric/tool-format failures prevent promotion. Base stays active.\n{ROOT/'verification/advertising-analysis-v2-review.json'}\n\nThe future256GBprofile remains unbenchmarked. Complete decompilation/full-game boot remain unfinished.\n''')
    for name in ['START HERE.txt','CURRENT DECOMPILATION.txt','CURRENT LOCAL INFERENCE.txt']:shutil.copy2(ROOT/name,out/('current-'+name))
    p=ROOT/'verification/NEXT SOURCE AND INFERENCE WORK.json';n=json.loads(p.read_text());n.update(local_audit=str(out),local_roles_this_turn=result,last_turn_classification='progress',new_training_this_turn=False);save(p,n)
    (ROOT/'training/feedback/firmware-post-GPU-20261015.jsonl').write_text(json.dumps(dict(directory=str(local),status=result['status'],used_in_weight_training=False,independent_heldout_eval=False))+'\n')
    assert all(hashlib.sha256(Path(x['snapshot']).read_bytes()).hexdigest()==x['sha256']for x in review['manifest'])
    print(json.dumps(result))

if __name__=='__main__':main()
